import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"55. Makefile 和构建自动化","description":"The Little Book of C 中文版 — 55. Makefile 和构建自动化","frontmatter":{"title":"55. Makefile 和构建自动化","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 55. Makefile 和构建自动化","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":55,"sidebarWeight":55,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/055-Makefiles and Build Automation","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/055-Makefiles and Build Automation"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/055-Makefiles and Build Automation.md","filePath":"posts/c教程/zh-CN/06-编译与构建/055-Makefiles and Build Automation.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/06-编译与构建/055-Makefiles and Build Automation.md"};function l(t,a,c,o,d,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/055-Makefiles and Build Automation)</p><p>手动编译一两个 C 文件就可以了，但实际项目很快就会增长到数十或数百个文件。打字时间长<code>gcc</code>每次执行命令都会变得乏味、容易出错并且在不同环境中不一致。</p><p>这就是 Makefile 的用武之地。它们自动化构建过程，跟踪依赖关系，并仅重建发生变化的部分。</p><p>让我们全面了解如何使用<code>make</code>并编写简单但功能强大的 Makefile。</p><h4 id="步骤-1-什么是-make" tabindex="-1">步骤 1. 什么是 make？ <a class="header-anchor" href="#步骤-1-什么是-make" aria-label="Permalink to &quot;步骤 1. 什么是 make？&quot;">​</a></h4><p><code>make</code>是一个读取名为 Makefile 的文件并执行它定义的构建规则的工具。</p><p>每条规则描述：</p><ol><li>目标（你想要构建的东西） 2.它的依赖（它需要什么）</li><li>构建命令</li></ol><p>基本语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>target: dependencies</span></span>
<span class="line"><span>&lt;TAB&gt;command</span></span></code></pre></div><p>是的，缩进必须是真正的制表符，而不是空格。</p><h4 id="步骤-2-最简单的-makefile" tabindex="-1">步骤 2. 最简单的 Makefile <a class="header-anchor" href="#步骤-2-最简单的-makefile" aria-label="Permalink to &quot;步骤 2. 最简单的 Makefile&quot;">​</a></h4><p>假设您的项目有：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.c</span></span>
<span class="line"><span>math.c</span></span>
<span class="line"><span>math.h</span></span></code></pre></div><p>生成文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.c math.c</span></span>
<span class="line"><span>    gcc main.c math.c -o app</span></span></code></pre></div><p>建造：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c math.c -o app</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./app</span></span></code></pre></div><p>现在如果你跑<code>make</code>再次，什么也没有发生，因为<code>make</code>看到输出（<code>app</code>）比来源更新。这就是依赖跟踪的魔力。</p><h4 id="步骤-3-分成编译步骤" tabindex="-1">步骤 3. 分成编译步骤 <a class="header-anchor" href="#步骤-3-分成编译步骤" aria-label="Permalink to &quot;步骤 3. 分成编译步骤&quot;">​</a></h4><p>更好的版本构建<code>.o</code>分别归档：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.o math.o</span></span>
<span class="line"><span>    gcc main.o math.o -o app</span></span>
<span class="line"><span>main.o: main.c math.h</span></span>
<span class="line"><span>    gcc -c main.c</span></span>
<span class="line"><span>math.o: math.c math.h</span></span>
<span class="line"><span>    gcc -c math.c</span></span></code></pre></div><p>现在当你只改变<code>math.c</code>， 仅有的<code>math.o</code>重新编译。</p><h4 id="小代码-最小项目" tabindex="-1">小代码：最小项目 <a class="header-anchor" href="#小代码-最小项目" aria-label="Permalink to &quot;小代码：最小项目&quot;">​</a></h4><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;2 + 3 = %d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>数学.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span></code></pre></div><p>数学.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b);</span></span></code></pre></div><p>生成文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.o math.o</span></span>
<span class="line"><span>    gcc main.o math.o -o app</span></span>
<span class="line"><span>main.o: main.c math.h</span></span>
<span class="line"><span>    gcc -c main.c</span></span>
<span class="line"><span>math.o: math.c math.h</span></span>
<span class="line"><span>    gcc -c math.c</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f *.o app</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./app</span></span>
<span class="line"><span>make clean</span></span></code></pre></div><h4 id="步骤-4-使用变量" tabindex="-1">步骤 4. 使用变量 <a class="header-anchor" href="#步骤-4-使用变量" aria-label="Permalink to &quot;步骤 4. 使用变量&quot;">​</a></h4><p>Makefile 支持变量以避免重复：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -Wextra -std=c99</span></span>
<span class="line"><span>OBJ = main.o math.o</span></span>
<span class="line"><span>app: $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(OBJ) -o app</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) app</span></span></code></pre></div><p>这里：</p><p>-<code>$&lt;</code>= 第一个依赖项 -<code>$@</code>= 目标名称 -<code>%.o: %.c</code>= 模式规则（适用于所有匹配文件）</p><h4 id="步骤-5-添加调试和发布模式" tabindex="-1">步骤 5. 添加调试和发布模式 <a class="header-anchor" href="#步骤-5-添加调试和发布模式" aria-label="Permalink to &quot;步骤 5. 添加调试和发布模式&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>DEBUG_FLAGS = -g -O0</span></span>
<span class="line"><span>RELEASE_FLAGS = -O2</span></span>
<span class="line"><span>OBJ = main.o math.o</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>all: release</span></span>
<span class="line"><span>debug: CFLAGS += $(DEBUG_FLAGS)</span></span>
<span class="line"><span>debug: $(TARGET)</span></span>
<span class="line"><span>release: CFLAGS += $(RELEASE_FLAGS)</span></span>
<span class="line"><span>release: $(TARGET)</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJ) -o $(TARGET)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p>在调试模式下构建：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make debug</span></span></code></pre></div><p>构建优化版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make release</span></span></code></pre></div><h4 id="步骤-6-自动依赖关系" tabindex="-1">步骤 6. 自动依赖关系 <a class="header-anchor" href="#步骤-6-自动依赖关系" aria-label="Permalink to &quot;步骤 6. 自动依赖关系&quot;">​</a></h4><p>你可以有<code>gcc</code>自动生成依赖文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -MMD -c main.c</span></span></code></pre></div><p>这创造了<code>main.d</code>它跟踪包含的标头。您可以将这些文件包含在 Makefile 中以进行自动重建：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-include $(OBJ:.o=.d)</span></span></code></pre></div><p>这就是专业构建系统保持依赖关系准确的方式。</p><h4 id="步骤-7-虚假目标" tabindex="-1">步骤 7. 虚假目标 <a class="header-anchor" href="#步骤-7-虚假目标" aria-label="Permalink to &quot;步骤 7. 虚假目标&quot;">​</a></h4><p>不生成实际文件的目标应标记为虚假目标：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.PHONY: clean all debug release</span></span></code></pre></div><p>这可以防止文件名冲突（例如，如果文件名为<code>clean</code>存在）。</p><h4 id="步骤-8-组织更大的项目" tabindex="-1">步骤 8. 组织更大的项目 <a class="header-anchor" href="#步骤-8-组织更大的项目" aria-label="Permalink to &quot;步骤 8. 组织更大的项目&quot;">​</a></h4><p>对于多目录项目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span> ├── main.c</span></span>
<span class="line"><span> ├── util.c</span></span>
<span class="line"><span>include/</span></span>
<span class="line"><span> ├── util.h</span></span></code></pre></div><p>您可以像这样构造您的 Makefile：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SRC = src/main.c src/util.c</span></span>
<span class="line"><span>OBJ = $(SRC:.c=.o)</span></span>
<span class="line"><span>CFLAGS = -Iinclude -Wall</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(OBJ) -o $@</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p><code>-Iinclude</code>告诉编译器在哪里可以找到头文件。</p><h4 id="步骤-9-使用内置规则" tabindex="-1">步骤 9. 使用内置规则 <a class="header-anchor" href="#步骤-9-使用内置规则" aria-label="Permalink to &quot;步骤 9. 使用内置规则&quot;">​</a></h4><p><code>make</code>已经知道如何构建<code>.o</code>从<code>.c</code>。一个极简的 Makefile 可以是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.o math.o</span></span>
<span class="line"><span>    gcc $^ -o $@</span></span></code></pre></div><p>在哪里<code>$^</code>扩展到所有依赖项（<code>main.o math.o</code>).</p><h4 id="步骤-10-小代码-库构建示例" tabindex="-1">步骤 10. 小代码：库构建示例 <a class="header-anchor" href="#步骤-10-小代码-库构建示例" aria-label="Permalink to &quot;步骤 10. 小代码：库构建示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>OBJ = util.o io.o</span></span>
<span class="line"><span>LIB = libtools.a</span></span>
<span class="line"><span>$(LIB): $(OBJ)</span></span>
<span class="line"><span>    ar rcs $(LIB) $(OBJ)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(LIB)</span></span></code></pre></div><p>构建您的静态库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>现在链接它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -ltools -o app</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>Makefile 为您提供：</p><ul><li>可重复的构建，每次都使用相同的命令</li><li>增量重新编译，仅更改文件重建</li><li>多种配置、调试、发布、测试</li><li>可扩展性，可以运行脚本、代码生成、打包等。</li></ul><p>每个严肃的 C 项目，从 Linux 内核到小型嵌入式工具，都依赖于<code>make</code>或其后代（如 CMake、Ninja、Meson）。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>1.创建一个项目有3<code>.c</code>文件和2<code>.h</code>文件。 2. 编写支持的Makefile<code>make debug</code>,<code>make release</code>， 和<code>make clean</code>. 3.添加一个<code>make install</code>将二进制文件复制到的目标<code>/usr/local/bin</code>. 4. 使用变量，如<code>CC</code>,<code>CFLAGS</code>和模式规则来简化您的文件列表。 5. 跑步<code>make -n</code>预览命令而不执行它们。</p><p>在下一节中，您将学习如何链接多个文件和库，了解目标文件、符号以及代码在构建过程中如何连接在一起。</p>`,82)])])}const g=s(i,[["render",l]]);export{r as __pageData,g as default};
